import{_ as t,o as a,c as r,ao as i}from"./chunks/framework.YvcYaEXU.js";const y=JSON.parse('{"title":"The library of formulations","description":"","frontmatter":{},"headers":[],"relativePath":"studio/library.md","filePath":"studio/library.md","lastUpdated":null}'),n={name:"studio/library.md"};function l(s,e,h,o,d,b){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="studio-library" tabindex="-1">The library of formulations <a class="header-anchor" href="#studio-library" aria-label="Permalink to &quot;The library of formulations {#studio-library}&quot;">​</a></h1><p>The <em>Start</em> tab of the studio offers formulations published in papers, each loaded with one click: every tab is then filled, and the calculation can be run at once, changed, and saved under a name of your own. Nothing is downloaded: the formulations ship with the studio, and the compositions they use are those ChemistryLab holds, with their sources, in its material templates.</p><p>Only formulations published in a paper are offered. Where an entry takes a proportion from its paper (a replacement, a water-to-binder ratio), the tests of the studio check it against the data ChemistryLab holds for that paper. The degrees of reaction are illustrative unless the entry says otherwise: set them for the age you are interested in, or let rate laws decide them.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Formulation</th><th style="text-align:right;">What it computes</th><th style="text-align:right;">Sources</th></tr></thead><tbody><tr><td style="text-align:right;">CEM I 52.5 N paste</td><td style="text-align:right;">one equilibrium at 28 days, w/b 0.5</td><td style="text-align:right;">(<a href="/ChemistryLab.jl/stable/references#Gruyaert2010">Gruyaert <em>et al.</em>, 2010</a>), (<a href="/ChemistryLab.jl/stable/references#LothenbachWinnefeld2006">Lothenbach and Winnefeld, 2006</a>)</td></tr><tr><td style="text-align:right;">Portland cement paste, RILEM round robin</td><td style="text-align:right;">one equilibrium; its volumes are unknown, three minor oxides having no sourced density</td><td style="text-align:right;">(<a href="/ChemistryLab.jl/stable/references#Durdzinski2017">Durdziński <em>et al.</em>, 2017</a>), (<a href="/ChemistryLab.jl/stable/references#LothenbachWinnefeld2006">Lothenbach and Winnefeld, 2006</a>)</td></tr><tr><td style="text-align:right;">Portland cement with 40 % slag, RILEM round robin</td><td style="text-align:right;">one equilibrium of the paste PC-S1, w/b 0.4</td><td style="text-align:right;">(<a href="/ChemistryLab.jl/stable/references#Durdzinski2017">Durdziński <em>et al.</em>, 2017</a>), (<a href="/ChemistryLab.jl/stable/references#LothenbachWinnefeld2006">Lothenbach and Winnefeld, 2006</a>)</td></tr><tr><td style="text-align:right;">Portland cement with 30 % siliceous fly ash, RILEM round robin</td><td style="text-align:right;">one equilibrium of the paste PC-SFA, w/b 0.4</td><td style="text-align:right;">(<a href="/ChemistryLab.jl/stable/references#Durdzinski2017">Durdziński <em>et al.</em>, 2017</a>), (<a href="/ChemistryLab.jl/stable/references#LothenbachWinnefeld2006">Lothenbach and Winnefeld, 2006</a>)</td></tr><tr><td style="text-align:right;">Slag cements: the replacement of a CEM I 52.5 N by slag</td><td style="text-align:right;">a path along the slag-to-binder ratios of the paper, 0 to 0.85</td><td style="text-align:right;">(<a href="/ChemistryLab.jl/stable/references#Gruyaert2010">Gruyaert <em>et al.</em>, 2010</a>), (<a href="/ChemistryLab.jl/stable/references#LothenbachWinnefeld2006">Lothenbach and Winnefeld, 2006</a>)</td></tr><tr><td style="text-align:right;">Hydration of a CEM I 52.5 N in time, by rate laws</td><td style="text-align:right;">a kinetic run over 28 days, the clinker phases by the law of <a href="/ChemistryLab.jl/stable/references#ParrottKilloh1984">Parrott and Killoh (1984)</a> with the parameters of <a href="/ChemistryLab.jl/stable/references#Lavergne2018">Lavergne <em>et al.</em> (2018)</a></td><td style="text-align:right;">(<a href="/ChemistryLab.jl/stable/references#Gruyaert2010">Gruyaert <em>et al.</em>, 2010</a>), (<a href="/ChemistryLab.jl/stable/references#Lavergne2018">Lavergne <em>et al.</em>, 2018</a>), (<a href="/ChemistryLab.jl/stable/references#LothenbachWinnefeld2006">Lothenbach and Winnefeld, 2006</a>)</td></tr><tr><td style="text-align:right;">Carbonation of a CEM I 52.5 N paste</td><td style="text-align:right;">a path of CO₂ added, up to 1 mol per 100 g of binder</td><td style="text-align:right;">(<a href="/ChemistryLab.jl/stable/references#Gruyaert2010">Gruyaert <em>et al.</em>, 2010</a>), (<a href="/ChemistryLab.jl/stable/references#LothenbachWinnefeld2006">Lothenbach and Winnefeld, 2006</a>)</td></tr><tr><td style="text-align:right;">Leaching of a CEM I 52.5 N paste by pure water</td><td style="text-align:right;">twelve renewals of the pore solution by 5 kg of water</td><td style="text-align:right;">(<a href="/ChemistryLab.jl/stable/references#Gruyaert2010">Gruyaert <em>et al.</em>, 2010</a>), (<a href="/ChemistryLab.jl/stable/references#LothenbachWinnefeld2006">Lothenbach and Winnefeld, 2006</a>)</td></tr></tbody></table><p>The phases of every entry are those <a href="/ChemistryLab.jl/stable/references#LothenbachWinnefeld2006">Lothenbach and Winnefeld (2006)</a> list for a Portland paste, in the thermodynamic database Cemdata18 (<a href="/ChemistryLab.jl/stable/references#Lothenbach2019">Lothenbach <em>et al.</em>, 2019</a>).</p>',5)])])}const m=t(n,[["render",l]]);export{y as __pageData,m as default};
